-- Segunda leva de ajustes da Controladoria (26/11/2026, fim do dia).
--   F3 cancelar chamado (status 'cancelada'; libera a reserva de saldo)
--   F4 tipo da Transferência (FL / Externo) só no destino; marcas FL e Externo por divisão (dado mestre)
--   F6 escopo de CCs (e divisões) por grupo
--   F7/F8 família da estrutura de obra (local e subgrupos) e código do nível da ordem
ALTER TABLE solicitacoes ADD COLUMN IF NOT EXISTS tipo_transferencia VARCHAR(10);
DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'solicitacoes_tipo_transferencia_check') THEN
        ALTER TABLE solicitacoes ADD CONSTRAINT solicitacoes_tipo_transferencia_check CHECK (tipo_transferencia IS NULL OR tipo_transferencia IN ('FL', 'Externo'));
    END IF;
END $$;

ALTER TABLE divisoes ADD COLUMN IF NOT EXISTS faz_fl BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE divisoes ADD COLUMN IF NOT EXISTS faz_externo BOOLEAN NOT NULL DEFAULT true;
-- carga inicial pedida (F4): FL = as 15 abaixo; Externo = todas, menos as 9 que são só FL
UPDATE divisoes SET faz_fl = true WHERE codigo IN ('0101','0102','0201','0301','0302','0401','0501','0601','0801','0901','0902','1007','0091','0092','0093');
UPDATE divisoes SET faz_externo = false WHERE codigo IN ('0102','0201','0301','0302','0401','0501','0601','0801','0901');

CREATE TABLE IF NOT EXISTS grupo_escopo (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    grupo_id UUID NOT NULL REFERENCES grupos(id) ON DELETE CASCADE,
    cc VARCHAR(4) NOT NULL,           -- os 4 últimos dígitos do centro de custo
    divisao VARCHAR(4),               -- NULL = todas as divisões
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_grupo_escopo ON grupo_escopo (grupo_id, cc, COALESCE(divisao, ''));

ALTER TABLE locais_obra ADD COLUMN IF NOT EXISTS tipo_estrutura VARCHAR(30);
ALTER TABLE subgrupos_despesa ADD COLUMN IF NOT EXISTS familias TEXT[];
ALTER TABLE obra_ordens ADD COLUMN IF NOT EXISTS codigo_nivel VARCHAR(30);

DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'fb_apu05_privilegiado') THEN
        GRANT SELECT ON grupo_escopo, divisoes, locais_obra, subgrupos_despesa TO fb_apu05_privilegiado;
        GRANT UPDATE (tipo_despesa, tipo_faturamento) ON obra_ordens TO fb_apu05_privilegiado;
    END IF;
END $$;

